return ['domain'=>'wpml-import','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Un plugin polivalente para exportar e importar contenido multilingüe.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'El activador de importación ya no acepta la clave en la URL. Envíela en el cuerpo de un POST.','Method Not Allowed'=>'Método no permitido','Unauthorized'=>'No autorizado','No items to process'=>'No hay elementos para procesar','No Content'=>'Sin contenido','Import process completed'=>'Proceso de importación completado','Success'=>'Éxito','Import process failed'=>'El proceso de importación ha fallado','Internal Server Error'=>'Error interno del servidor','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d elemento no pudo procesarse y se omitió.' . "\0" . '%1$s: %2$d elementos no pudieron procesarse y se omitieron.','Cleaning Up Post Data'=>'Limpieza de los datos de las entradas','Removing temporary and import-related post meta data.'=>'Eliminando metadatos de las entradas temporales y relacionados con la importación.','Cleaning Up Term Data'=>'Limpieza de los datos de los términos','Removing temporary and import-related term meta data.'=>'Eliminando metadatos de los términos temporales y relacionados con la importación.','Connecting Post Image Attachments'=>'Vinculación de los adjuntos de imagen de las entradas','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Actualizando los ID de los adjuntos de miniaturas y galerías en las entradas, productos y CPT traducidos para que apunten a sus equivalentes traducidos.','Connecting Inline Term Translations'=>'Vinculación de las traducciones de términos en línea','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Escaneando entradas con un único término de taxonomía para identificar y vincular los términos asignados a estas entradas con sus traducciones.','Deleting Obsolete Original Terms'=>'Eliminación de términos originales obsoletos','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Eliminando términos originales que ya no son necesarios tras crear duplicados para términos con el mismo nombre. Asegurando que ninguna entrada esté vinculada a estos términos originales.','Duplicating Terms with Shared Names Across Languages'=>'Duplicación de términos con nombres compartidos entre idiomas','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Creando duplicados en el idioma correcto para los términos que comparten el mismo nombre en varios idiomas, pero que pertenecen a entradas en idiomas diferentes.','Fixing Imported Post Slugs'=>'Corrección de los slugs de las entradas importadas','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Regenerando los slugs de las entradas traducidas para evitar conflictos con los originales.','Clearing Translations Cache'=>'Vaciado de la caché de traducciones','Invalidating the persistent cache so it can be regenerated.'=>'Invalidando la caché persistente para que pueda ser regenerada.','Marking Parent Terms for Connection'=>'Marcado de términos padre para su vinculación','Collecting parent terms to connect their translations in the next step.'=>'Recopilando términos padre para vincular sus traducciones en el siguiente paso.','Connecting Posts with Correct Term Translations'=>'Vinculación de entradas con las traducciones de términos correctas','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Asegurando que las entradas estén vinculadas a los términos en el idioma correcto, especialmente si tiene los mismos nombres de términos en varios idiomas.','Sending Posts for Automatic Translation'=>'Envío de entradas para traducción automática','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Creando trabajos de traducción automática para las entradas marcadas para traducción automática en los datos exportados.','Setting Attachments\' Language'=>'Asignación del idioma de los adjuntos','Assigning a language to imported attachments.'=>'Asignando un idioma a los adjuntos importados.','Updating Final Post Status'=>'Actualización del estado final de la entrada','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Estableciendo el estado de la entrada basándose en el campo “_wpml_import_after_process_post_status” del archivo de importación (si se ha proporcionado).','Identifying Inline Term Languages'=>'Identificación de los idiomas de los términos en línea','Identifying and setting the language of terms created during post imports.'=>'Identificando y estableciendo el idioma de los términos creados durante las importaciones de entradas.','Setting Posts’ Language'=>'Asignación del idioma de las entradas','Connecting posts to the default language and translations.'=>'Vinculando entradas al idioma predeterminado y a las traducciones.','Setting Terms’ Language'=>'Asignación del idioma de los términos','Connecting taxonomy terms to the default (original) language and translations.'=>'Vinculando términos de taxonomía al idioma predeterminado (original) y a las traducciones.','Setting Parent Terms\' Language'=>'Asignación del idioma de los términos padre','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Asignando idioma a los términos de taxonomía padre que no tienen uno, basándose en el idioma asignado a sus hijos.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'¿Va a migrar su sitio multilingüe? Recuerde instalar también %s en su nuevo sitio antes de importar el contenido para que podamos restaurar todas las traducciones.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'¿Va a migrar su tienda multilingüe? Con %1$s y %2$s puede transferir su contenido traducido a un nuevo sitio, incluyendo ventas cruzadas, ventas dirigidas y atributos de producto.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'¿Va a migrar su tienda multilingüe? Recuerde instalar %1$s y %2$s en su nuevo sitio antes de importar el contenido para que podamos restaurar todas las traducciones.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'¿Desea importar su contenido multilingüe? Recuerde instalar %s en su sitio original antes de exportar su contenido para que podamos importar todas las traducciones aquí.','Looking to import your multilingual content? Install %1$s on this site.'=>'¿Desea importar su contenido multilingüe? Instale %1$s en este sitio.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Recuerde también activar %2$s y %3$s en su tienda original antes de exportar su contenido para que podamos importar todas las traducciones aquí.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'¿Desea importar su contenido multilingüe? Recuerde activar %1$s y %2$s en su tienda original antes de exportar su contenido para que podamos importar todas las traducciones aquí.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Cambiar a todos los idiomas','Linking Product Attribute Translations'=>'Vinculación de las traducciones de atributos de producto','Connecting product attributes to their translations based on associated product variations.'=>'Vinculando atributos de producto con sus traducciones basándose en las variaciones de producto asociadas.','Updating Related Products On Translations'=>'Actualización de productos relacionados en las traducciones','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Configurando las referencias de ventas dirigidas, ventas cruzadas y productos agrupados en el idioma correcto.','Importing Custom Attribute Labels'=>'Importación de etiquetas de atributos personalizados','Importing labels for product-specific (custom) attributes from the exported data.'=>'Importando etiquetas para atributos específicos de producto (personalizados) desde los datos exportados.','You are about to export all your products in all languages at once.'=>'Está a punto de exportar todos sus productos en todos los idiomas a la vez.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Recuerde instalar %1$s y %2$s en su nuevo sitio antes de importar el contenido para que podamos restaurar todas las traducciones.','You are about to export your products in %s.'=>'Está a punto de exportar sus productos en %s.','Registering Product Attributes'=>'Registro de atributos de producto','Identifying and registering attributes created during product imports for translation.'=>'Identificando y registrando para traducción los atributos creados durante las importaciones de productos.','Identifying Product Attribute Languages'=>'Identificación de los idiomas de los atributos de producto','Identifying and setting the language of attributes created during product imports.'=>'Identificando y estableciendo el idioma de los atributos creados durante las importaciones de productos.','Export and Import'=>'Exportar e importar','I’m using the built-in %s export/import tool'=>'Estoy usando la herramienta de exportación/importación integrada de %s','I’m using %s plugin'=>'Estoy usando el plugin %s','(%1$d/%2$d items)'=>'(%1$d/%2$d elementos)','%d skipped'=>'%d omitidos','(no items)'=>'(sin elementos)','Counting items...'=>'Contando elementos...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Primero, díganos cómo va a crear el contenido que va a importar:','Continue'=>'Continuar','I’m using %1$s and %2$s plugins'=>'Estoy usando los plugins %1$s y %2$s','I’m using a different method to export from this site'=>'Estoy usando un método diferente para exportar desde este sitio','I’m exporting the content from this site'=>'Estoy exportando el contenido desde este sitio','I’m exporting the content from a different website or system'=>'Estoy exportando el contenido desde un sitio web o sistema diferente','Before importing, add language columns to your content'=>'Antes de importar, añada columnas de idioma a su contenido','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Asegúrese de que su archivo de importación incluya las siguientes columnas (campos personalizados) con información de idioma:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: un valor que sea el mismo para todas las traducciones de cada elemento. En sitios de comercio electrónico, a menudo será el SKU.','%s: The language code for each item.'=>'%s: el código de idioma de cada elemento.','And, you can include these two columns if needed:'=>'Y puede incluir estas dos columnas si es necesario:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: si este elemento es una traducción, establezca esta columna con el código del idioma de origen. Si no es una traducción, déjela vacía.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: establézcalo como “borrador” o “publicado” para determinar el estado de publicación de la entrada tras ajustar los idiomas. Normalmente, este valor será “publicado”.','Here is an example of importing two items, into your site’s languages (%s):'=>'Aquí tiene un ejemplo de importación de dos elementos en los idiomas de su sitio (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Una vez que haya añadido las columnas de idioma a su archivo de contenido multilingüe, impórtelo a su sitio utilizando el plugin de importación que prefiera.','Before importing, your content needs language information'=>'Antes de importar, su contenido necesita información de idioma','%s will add the necessary language information to your export.'=>'%s añadirá la información de idioma necesaria a su exportación.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Importe su archivo de contenido multilingüe al sitio utilizando el plugin de importación que prefiera.','Use your favorite import plugin'=>'Utilice su plugin de importación favorito','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Después de importar el contenido, este seguirá sin mostrar la información de idioma correcta. Por ello, le recomendamos que importe el contenido nuevo como borradores. Si está importando actualizaciones, puede mantener el contenido ya publicado como publicado.','Return here, to %s, to set languages and connect translations'=>'Vuelva aquí, a %s, para establecer los idiomas y vincular las traducciones','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Cuando visite esta página después de haber importado contenido con información de idioma, podrá ejecutar %s para aplicar los idiomas y vincular las traducciones.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'¿Ya ha realizado la importación y sigue viendo esta pantalla? %1$sSolución de problemas de %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Cómo exportar e importar contenido en varios idiomas','%s is ready to update your imported content'=>'%s está listo para actualizar su contenido importado','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Buen trabajo. Vemos %1$d términos y %2$d entradas que se han importado y necesitan información de idioma.','Good job. We see %d terms that are imported and need language information.'=>'Buen trabajo. Vemos %d términos que se han importado y necesitan información de idioma.','Good job. We see %d posts that are imported and need language information.'=>'Buen trabajo. Vemos %d entradas que se han importado y necesitan información de idioma.','Run WPML Import'=>'Ejecutar WPML Import','Multilingual Import Complete'=>'Importación multilingüe completada']];